feature ! { #! [unix] impl OpenOptions { # [doc = " Sets the mode bits that a new file will be created with."] # [doc = ""] # [doc = " If a new file is created as part of an `OpenOptions::open` call then this"] # [doc = " specified `mode` will be used as the permission bits for the new file."] # [doc = " If no `mode` is set, the default of `0o666` will be used."] # [doc = " The operating system masks out bits with the system's `umask`, to produce"] # [doc = " the final permissions."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use tokio::fs::OpenOptions;"] # [doc = " use std::io;"] # [doc = ""] # [doc = " #[tokio::main]"] # [doc = " async fn main() -> io::Result<()> {"] # [doc = "     let mut options = OpenOptions::new();"] # [doc = "     options.mode(0o644); // Give read/write for owner and read for others."] # [doc = "     let file = options.open(\"foo.txt\").await?;"] # [doc = ""] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] pub fn mode (& mut self , mode : u32) -> & mut OpenOptions { match & mut self . inner { Kind :: Std (opts) => { opts . mode (mode) ; } # [cfg (all (tokio_unstable , feature = "io-uring" , feature = "rt" , feature = "fs" , target_os = "linux"))] Kind :: Uring (opts) => { opts . mode (mode) ; } } self } # [doc = " Passes custom flags to the `flags` argument of `open`."] # [doc = ""] # [doc = " The bits that define the access mode are masked out with `O_ACCMODE`, to"] # [doc = " ensure they do not interfere with the access mode set by Rusts options."] # [doc = ""] # [doc = " Custom flags can only set flags, not remove flags set by Rusts options."] # [doc = " This options overwrites any previously set custom flags."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use tokio::fs::OpenOptions;"] # [doc = " use std::io;"] # [doc = ""] # [doc = " #[tokio::main]"] # [doc = " async fn main() -> io::Result<()> {"] # [doc = "     let mut options = OpenOptions::new();"] # [doc = "     options.write(true);"] # [doc = "     if cfg!(unix) {"] # [doc = "         options.custom_flags(libc::O_NOFOLLOW);"] # [doc = "     }"] # [doc = "     let file = options.open(\"foo.txt\").await?;"] # [doc = ""] # [doc = "     Ok(())"] # [doc = " }"] # [doc = " ```"] pub fn custom_flags (& mut self , flags : i32) -> & mut OpenOptions { match & mut self . inner { Kind :: Std (opts) => { opts . custom_flags (flags) ; } # [cfg (all (tokio_unstable , feature = "io-uring" , feature = "rt" , feature = "fs" , target_os = "linux"))] Kind :: Uring (opts) => { opts . custom_flags (flags) ; } } self } } }